<?php
function page_assistance(): void {
 need_login();heading('SUPPORT COORDINATION','Assistance requests','Tell us what support you need and follow updates from the assigned team.');
 $params=[];$where='';if(!can('respond')){$where=' WHERE a.user_id=?';$params[]=user()['id'];}elseif(!can('coordinate')){$where=' WHERE a.assigned_to=?';$params[]=user()['id'];}
 $status=(string)($_GET['status']??'');if($status){$where.=($where?' AND ':' WHERE ').'a.status=?';$params[]=$status;}
 echo '<form class="filters" method="get"><input type="hidden" name="page" value="assistance">';select('status','Filter status',[''=>'All requests','submitted'=>'Submitted','reviewing'=>'Reviewing','assigned'=>'Assigned','in_progress'=>'In progress','fulfilled'=>'Fulfilled','cancelled'=>'Cancelled'],$status);echo '<button class="button secondary">Apply</button></form>';
 $count=(int)scalar('SELECT COUNT(*) FROM assistance_requests a'.$where,$params);$offset=(max(1,(int)($_GET['p']??1))-1)*10;$rows=all('SELECT a.*,u.name requester,t.name team FROM assistance_requests a JOIN users u ON u.id=a.user_id LEFT JOIN users t ON t.id=a.assigned_to'.$where.' ORDER BY a.created_at DESC LIMIT 10 OFFSET '.$offset,$params);
 echo '<div class="request-grid">';if(!$rows)empty_state('No requests yet','Requests and their progress will appear here.');foreach($rows as $r){echo '<article class="card padded"><div class="badge-row">'.badge($r['status']).'<small>#'.e($r['id']).' · '.e($r['created_at']).'</small></div><h2>'.e($r['category']).'</h2><p class="preserve">'.e($r['description']).'</p><p><strong>'.e($r['area']).'</strong> · '.e($r['people']).' people<br>Location: '.e($r['latitude']).', '.e($r['longitude']).'<br>Address / landmark: '.e($r['address']?:'Not recorded').'</p><p class="muted">Requester: '.e($r['requester']).'<br>Assigned team member: '.e($r['team']??'Not assigned').'</p>';if($r['note'])echo '<div class="notice"><strong>Latest update</strong><p>'.e($r['note']).'</p></div>';if(can('respond')){echo '<details><summary>Update request</summary>';start_form('request_update');echo '<input type="hidden" name="id" value="'.e($r['id']).'">';select('status','New status',['submitted'=>'Submitted','reviewing'=>'Reviewing','assigned'=>'Assigned','in_progress'=>'In progress','fulfilled'=>'Fulfilled','cancelled'=>'Cancelled'],$r['status']);if(can('coordinate'))select('assigned_to','Response team member',[0=>'Not assigned']+array_column(all("SELECT id,name FROM users WHERE role IN ('admin','authority','responder') AND active=1"),'name','id'),$r['assigned_to']??0);textarea('note','Update for requester','',5,3000);end_form('Update request');echo '</details>';}echo '</article>';}echo '</div>';pager($count,10,'assistance',['status'=>$status]);
 start_form('assistance','Request emergency support');select('category','What support is needed?',array_combine(['Medical assistance','Evacuation support','Food and water','Shelter','Rescue assistance','Other'],['Medical assistance','Evacuation support','Food and water','Shelter','Rescue assistance','Other']));textarea('description','Describe the assistance needed','',20);location_fields();field('people','Number of people needing support','number',1,true,'min="1" max="1000000"');echo '<p class="hint">Our system records requests for staff to review. Submitting a request does not automatically dispatch emergency services.</p>';end_form('Submit assistance request');
}
function page_volunteers(): void {
 need_login();heading('PEOPLE WHO MAKE A DIFFERENCE','Volunteer hub','Share your skills and availability, and follow tasks assigned by a coordinator.');$u=user();$v=one('SELECT * FROM volunteers WHERE user_id=?',[$u['id']])??[];echo '<section class="volunteer-intro card"><figure>'.visual_image('community','volunteer-photo',false,'(max-width: 600px) calc(100vw - 32px), 330px').'</figure><div><p class="eyebrow">COMMUNITY VOLUNTEERS</p><h2>Help your community</h2><p>Share your skills and availability. Coordinators assign approved tasks, and volunteers can track each assignment here.</p></div></section>';
 if(!can('coordinate')){start_form('volunteer_profile','My volunteer profile');field('skills','Skills (comma-separated)','text',$v['skills']??'',true,'minlength="3" maxlength="255"');textarea('experience','Relevant experience',$v['experience']??'',0,3000);echo '<div class="form-grid">';select('availability','Availability',['available'=>'Available','limited'=>'Limited availability','unavailable'=>'Unavailable'],$v['availability']??'available');field('service_area','Preferred service area','text',$v['service_area']??$u['area'],true,'maxlength="100"');echo '</div>';end_form('Save volunteer profile');}
 if(can('coordinate')) {$q=trim((string)($_GET['q']??''));echo '<form class="filters" method="get"><input type="hidden" name="page" value="volunteers">';field('q','Search skills, area or name','search',$q,false);echo '<button class="button secondary">Find volunteers</button></form>';$rows=all('SELECT v.*,u.name,u.email,u.active FROM volunteers v JOIN users u ON u.id=v.user_id WHERE u.active=1 AND (v.skills LIKE ? OR v.service_area LIKE ? OR u.name LIKE ?) ORDER BY v.availability,u.name',['%'.$q.'%','%'.$q.'%','%'.$q.'%']);echo '<section class="card"><div class="card-head"><h2>Volunteer directory</h2></div><div class="table-wrap"><table><thead><tr><th>Volunteer</th><th>Skills</th><th>Area</th><th>Availability</th></tr></thead><tbody>';foreach($rows as $v)echo '<tr><td>'.e($v['name']).'<small>'.e($v['experience']).'</small></td><td>'.e($v['skills']).'</td><td>'.e($v['service_area']).'</td><td>'.badge($v['availability']).'</td></tr>';echo '</tbody></table></div></section>';start_form('assignment','Create a volunteer assignment');echo '<div class="form-grid">';select('volunteer_id','Volunteer',array_column(array_filter($rows,fn($v)=>$v['availability']!=='unavailable'),'name','user_id'));select('report_id','Related verified incident',[0=>'General coordination']+array_column(all("SELECT id,CONCAT('#',id,' · ',title) label FROM reports WHERE status='verified'"),'label','id'));field('title','Assignment title','text','',true,'minlength="5" maxlength="150"');field('area','Service area','text','',true,'maxlength="100"');field('due_at','Due date and time','datetime-local',date('Y-m-d\TH:i',time()+86400));echo '</div>';textarea('instructions','Assignment instructions','',10,3000);end_form('Assign and notify volunteer');}
 $where=can('coordinate')?'':' WHERE a.volunteer_id=?';$params=can('coordinate')?[]:[$u['id']];$count=(int)scalar('SELECT COUNT(*) FROM volunteer_assignments a'.$where,$params);$offset=(max(1,(int)($_GET['p']??1))-1)*10;$rows=all('SELECT a.*,u.name volunteer FROM volunteer_assignments a JOIN users u ON u.id=a.volunteer_id'.$where.' ORDER BY a.id DESC LIMIT 10 OFFSET '.$offset,$params);echo '<div class="section-head"><h2>'.(can('coordinate')?'Assignment activity':'My assignments').'</h2></div><div class="request-grid">';if(!$rows)empty_state('No assignments yet','Approved tasks will appear here.');foreach($rows as $a){echo '<article class="card padded"><div class="badge-row">'.badge($a['status']).'<small>#'.e($a['id']).'</small></div><h2>'.e($a['title']).'</h2><p>'.e($a['instructions']).'</p><p>'.e($a['volunteer']).' · '.e($a['area']).'<br>Due '.e($a['due_at']).'</p>';if($a['report_id'])echo '<a href="'.url('report',['id'=>$a['report_id']]).'">Related incident #'.e($a['report_id']).'</a>';$opts=can('coordinate')?['assigned','accepted','in_progress','completed','declined','cancelled']:(['assigned'=>['accepted','declined'],'accepted'=>['in_progress','declined'],'in_progress'=>['completed']][$a['status']]??[]);if($opts){start_form('assignment_update');echo '<input type="hidden" name="id" value="'.e($a['id']).'">';select('status','Update assignment',array_combine($opts,array_map(fn($s)=>ucfirst(str_replace('_',' ',$s)),$opts)));end_form('Update assignment');}echo '</article>';}echo '</div>';pager($count,10,'volunteers');
}
function page_resources(): void {
 need('coordinate');heading('SUPPLY COORDINATION','Resource inventory','Track stock, record distributions and transfer matching items between locations.');$rows=all('SELECT * FROM resources ORDER BY name,location');metrics([['Inventory items',count($rows),'Across recorded locations','resources'],['Low-stock items',count(array_filter($rows,fn($r)=>$r['quantity']<=$r['minimum_quantity'])),'At or below minimum level','alerts'],['Stock transactions',scalar('SELECT COUNT(*) FROM resource_transactions'),'Recorded stock movements','audit'],['Storage locations',scalar('SELECT COUNT(DISTINCT location) FROM resources'),'Inventory locations','map']]);
 echo '<section class="card"><div class="table-wrap"><table><thead><tr><th>Item</th><th>Location</th><th>Available stock</th><th>Minimum</th><th>State</th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td>'.e($r['name']).'<small>'.e($r['category']).' · #'.e($r['id']).'</small></td><td>'.e($r['location']).'</td><td><strong>'.e($r['quantity']).'</strong> '.e($r['unit']).'</td><td>'.e($r['minimum_quantity']).'</td><td>'.badge($r['quantity']<=$r['minimum_quantity']?'Low':'available').'</td></tr>';echo '</tbody></table></div></section><div class="two-columns">';start_form('stock','Record stock movement');select('resource_id','Inventory item',array_column(array_map(fn($r)=>['id'=>$r['id'],'label'=>$r['name'].' · '.$r['location'].' (#'.$r['id'].')'],$rows),'label','id'));select('kind','Movement',['received'=>'Receive stock','distributed'=>'Distribute stock','transfer'=>'Transfer to another location']);field('quantity','Quantity','number',1,true,'min="0.01" max="10000000" step="0.01"');field('destination','Source / destination','text','',true,'maxlength="150"');select('target_resource_id','Destination item (transfers only)',[0=>'Select matching item at destination']+array_column(array_map(fn($r)=>['id'=>$r['id'],'label'=>$r['name'].' · '.$r['location'].' (#'.$r['id'].')'],$rows),'label','id'));textarea('note','Movement note','',3,3000);end_form('Record stock movement');start_form('resource','Add an inventory item');field('name','Item name','text','',true,'minlength="3" maxlength="100"');select('category','Category',array_combine(['Food','Water','Medicine','Equipment','Transport','Other'],['Food','Water','Medicine','Equipment','Transport','Other']));field('unit','Unit (e.g. packs, litres)','text','',true,'maxlength="30"');field('location','Storage location','text','',true,'maxlength="100"');field('minimum_quantity','Low-stock threshold','number',0,true,'min="0" step="0.01"');echo '<p class="hint">New items start with zero stock. Record receipts to establish the opening balance.</p>';end_form('Create inventory item');echo '</div><section class="card"><div class="card-head"><h2>Transaction ledger</h2></div><div class="table-wrap"><table><thead><tr><th>Recorded</th><th>Item</th><th>Movement</th><th>Quantity</th><th>Destination / source</th><th>Recorded by</th></tr></thead><tbody>';
 $count=(int)scalar('SELECT COUNT(*) FROM resource_transactions');$offset=(max(1,(int)($_GET['p']??1))-1)*15;foreach(all('SELECT t.*,r.name,r.unit,u.name actor FROM resource_transactions t JOIN resources r ON r.id=t.resource_id JOIN users u ON u.id=t.user_id ORDER BY t.id DESC LIMIT 15 OFFSET '.$offset) as $t)echo '<tr><td>'.e($t['created_at']).'</td><td>'.e($t['name']).'</td><td>'.badge($t['kind']).'</td><td>'.e($t['quantity']).' '.e($t['unit']).'</td><td>'.e($t['destination']).'<small>'.e($t['note']).'</small></td><td>'.e($t['actor']).'</td></tr>';echo '</tbody></table></div></section>';pager($count,15,'resources');
}
